(r, big) => {
  const m = big ? 500 : r.int(1, 5), n = big ? 500 : r.int(1, 6);
  const w = big ? ["#", "#", ".", ".", "*"] : r.pick([["#", ".", "*"], ["#", "#", "."], ["#", ".", ".", "*"]]);
  const g = [];
  for (let i = 0; i < m; i++) { const row = []; for (let j = 0; j < n; j++) row.push(r.pick(w)); g.push(row); }
  return [g];
}

