function tipCrate(crate: string[][]): string[][] {
  const m = crate.length, n = crate[0].length;
  const g = crate.map(row => row.slice());
  for (const row of g) {
    let moved = true;
    while (moved) {
      moved = false;
      for (let j = n - 2; j >= 0; j--) {
        if (row[j] === "#" && row[j + 1] === ".") { row[j] = "."; row[j + 1] = "#"; moved = true; }
      }
    }
  }
  const out: string[][] = Array.from({ length: n }, () => new Array(m));
  for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) out[j][m - 1 - i] = g[i][j];
  return out;
}

