    def tipCrate(self, crate: List[List[str]]) -> List[List[str]]:
        m, n = len(crate), len(crate[0])
        g = [row[:] for row in crate]
        for row in g:
            moved = True
            while moved:
                moved = False
                for j in range(n - 2, -1, -1):
                    if row[j] == "#" and row[j + 1] == ".":
                        row[j], row[j + 1] = ".", "#"
                        moved = True
        return [[g[m - 1 - i][j] for i in range(m)] for j in range(n)]

